impl<'a> ToTlv for WebRTCSessionStruct<'a> {
    fn to_tlv(&self, w: &mut TlvWriter<'_>, tag: Tag) -> Result<()> {
        w.start_structure(tag)?;
        self.id.to_tlv(w, Tag::Context(0))?;
        self.peer_node_id.to_tlv(w, Tag::Context(1))?;
        self.peer_endpoint_id.to_tlv(w, Tag::Context(2))?;
        self.stream_usage.to_tlv(w, Tag::Context(3))?;
        if let Some(value) = &self.video_stream_id {
            value.to_tlv(w, Tag::Context(4))?;
        }
        if let Some(value) = &self.audio_stream_id {
            value.to_tlv(w, Tag::Context(5))?;
        }
        self.metadata_enabled.to_tlv(w, Tag::Context(6))?;
        if let Some(value) = &self.video_streams {
            value.to_tlv(w, Tag::Context(7))?;
        }
        if let Some(value) = &self.audio_streams {
            value.to_tlv(w, Tag::Context(8))?;
        }
        self.fabric_index.to_tlv(w, Tag::Context(254))?;
        w.end_container()
    }
}

impl<'a> FromTlv<'a> for WebRTCSessionStruct<'a> {
    fn from_tlv(reader: &mut TlvReader<'a>, element: &Element<'a>) -> Result<Self> {
        if element.value.container() != Some(ContainerKind::Structure) {
            return Err(crate::Error::new(crate::ErrorCode::TlvWrongType));
        }
        let mut id = None;
        let mut peer_node_id = None;
        let mut peer_endpoint_id = None;
        let mut stream_usage = None;
        let mut video_stream_id = None;
        let mut audio_stream_id = None;
        let mut metadata_enabled = None;
        let mut video_streams = None;
        let mut audio_streams = None;
        let mut fabric_index = None;
        loop {
            let Some(field) = reader.next_element()? else {
                return Err(crate::Error::new(crate::ErrorCode::TlvTruncated));
            };
            if field.value == Value::EndOfContainer {
                break;
            }
            match field.tag.context() {
                Some(0) => id = Some(<u16>::from_tlv(reader, &field)?),
                Some(1) => peer_node_id = Some(<crate::msg::NodeId>::from_tlv(reader, &field)?),
                Some(2) => peer_endpoint_id = Some(<u16>::from_tlv(reader, &field)?),
                Some(3) => stream_usage = Some(<StreamUsageEnum>::from_tlv(reader, &field)?),
                Some(4) => video_stream_id = Some(<Nullable<u16>>::from_tlv(reader, &field)?),
                Some(5) => audio_stream_id = Some(<Nullable<u16>>::from_tlv(reader, &field)?),
                Some(6) => metadata_enabled = Some(<bool>::from_tlv(reader, &field)?),
                Some(7) => video_streams = Some(<TlvList<'a, u16>>::from_tlv(reader, &field)?),
                Some(8) => audio_streams = Some(<TlvList<'a, u16>>::from_tlv(reader, &field)?),
                Some(254) => {
                    fabric_index = Some(<crate::msg::FabricIndex>::from_tlv(reader, &field)?)
                }
                // A field this revision does not define. §7.19.2: a receiver
                // ignores what it does not know rather than refusing the whole
                // structure, which is what lets a newer peer talk to an older one.
                _ => reader.skip_value(&field)?,
            }
        }
        Ok(Self {
            id: id.ok_or(crate::Error::new(crate::ErrorCode::TlvNotFound))?,
            peer_node_id: peer_node_id.ok_or(crate::Error::new(crate::ErrorCode::TlvNotFound))?,
            peer_endpoint_id: peer_endpoint_id
                .ok_or(crate::Error::new(crate::ErrorCode::TlvNotFound))?,
            stream_usage: stream_usage.ok_or(crate::Error::new(crate::ErrorCode::TlvNotFound))?,
            video_stream_id,
            audio_stream_id,
            metadata_enabled: metadata_enabled
                .ok_or(crate::Error::new(crate::ErrorCode::TlvNotFound))?,
            video_streams,
            audio_streams,
            fabric_index: fabric_index.ok_or(crate::Error::new(crate::ErrorCode::TlvNotFound))?,
        })
    }
}
